    /**
     * Idempotently seeds default food units and food items if they are missing.
     * Existing records and user modifications are strictly preserved.
     */
    fun ensureDefaultFoodData(database: Database) {
        database.transaction {
            // 1. Ensure Default Units exist
            for (unit in DefaultUnits) {
                if (database.foodUnitQueries.selectById(unit.id).executeAsOneOrNull() == null) {
                    database.foodUnitQueries.insert(
                        id = unit.id,
                        name = unit.name,
                        abbreviation = unit.abbreviation,
                        isDefault = 1L,
                        updated_at = 0L
                    )
                }
            }

            // 2. Ensure Default Food Items exist
            for (food in DefaultFoods) {
                if (database.foodItemQueries.selectById(food.id).executeAsOneOrNull() == null) {
                    database.foodItemQueries.insert(
                        id = food.id,
                        name = food.name,
                        brand = food.brand,
                        upc = food.upc,
                        description = food.description,
                        unitName = food.unitName,
                        unitQuantity = food.unitQuantity,
                        caloriesPerUnit = food.caloriesPerUnit,
                        updated_at = 0L
                    )
                }
            }
        }
    }
}
